import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, texture, mul, add, sub, uniform, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ─────────────────────────────────────────────────────────────────
  // 1. STAGE: dark gradient backdrop plane
  // ─────────────────────────────────────────────────────────────────
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicMaterial({
    color: 0x0b0b10,
  });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = 0;
  group.add(backdrop);

  // ─────────────────────────────────────────────────────────────────
  // 2. PARALLAX PLANE: tessellated geometry + displacement TSL
  // ─────────────────────────────────────────────────────────────────
  const planeGeom = new THREE.PlaneGeometry(3, 2, 64, 64);

  // Load textures via ctx loaders
  let baseTex = null;
  let depthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      baseTex = tex;
      baseTex.flipY = false;
      material.colorMap = baseTex;
      material.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      depthTex.flipY = false;
      material.displacementMap = depthTex;
      material.needsUpdate = true;
    });
  }

  // TSL displacement node: sample depth map and displace vertices
  const displacementIntensity = uniform(0.15);
  const displacementNode = mul(
    texture(depthTex),
    displacementIntensity
  );

  const material = new MeshStandardNodeMaterial({
    colorMap: baseTex,
    displacementMap: depthTex,
    metalness: 0.45,
    roughness: 0.6,
    clearcoat: 0.2,
    clearcoatRoughness: 0.25,
  });

  // Manually set displacement in position node (TSL)
  material.positionNode = add(
    uv().mul(vec3(1, 1, 1)).sub(vec3(0.5, 0.5, 0)),
    mul(
      texture(depthTex).r,
      displacementIntensity,
      vec3(0, 0, 1)
    )
  );

  const plane = new THREE.Mesh(planeGeom, material);
  plane.position.copy(new THREE.Vector3(
    config.scenePosition?.[0] ?? 1.25,
    config.scenePosition?.[1] ?? -0.2,
    config.scenePosition?.[2] ?? 0
  ));
  plane.rotation.order = 'YXZ';
  plane.renderOrder = 1;
  group.add(plane);

  // ─────────────────────────────────────────────────────────────────
  // 3. ACCENT RIM LIGHT (hero-grade: engineered back light)
  // ─────────────────────────────────────────────────────────────────
  const rimLight = new THREE.PointLight(0xff2a38, 0.8, 8);
  rimLight.position.set(-2, 1.5, 1.5);
  group.add(rimLight);

  // ─────────────────────────────────────────────────────────────────
  // 4. CONTACT SHADOW under the plane
  // ─────────────────────────────────────────────────────────────────
  const shadowGeom = new THREE.CircleGeometry(1.5, 32);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.45,
  });
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.1, -0.05);
  shadow.rotation.x = -Math.PI / 2;
  shadow.renderOrder = 0.5;
  group.add(shadow);

  // ─────────────────────────────────────────────────────────────────
  // 5. CINEMATIC PRIMITIVES
  // ─────────────────────────────────────────────────────────────────
  const primitivesResults = [];

  // parallax-scroll on scroll
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name === 'parallax-scroll') {
        const result = ctx.primitives['parallax-scroll'](plane, prim.params || { intensity: 0.4 });
        primitivesResults.push(result);
      }
      if (prim.name === 'depth-rotate') {
        const result = ctx.primitives['depth-rotate'](plane, prim.params || { maxDeg: 8 });
        primitivesResults.push(result);
      }
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // 6. INTERACTIONS
  // ─────────────────────────────────────────────────────────────────
  const timelines = [];

  // Hover: subtle rise-in (0.15 scene units)
  const onHover = () => {
    gsap.killTweensOf(plane.position);
    const tl = gsap.timeline();
    tl.to(plane.position, {
      y: plane.position.y + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
    timelines.push(tl);
  };

  const onHoverOut = () => {
    gsap.killTweensOf(plane.position);
    const tl = gsap.timeline();
    tl.to(plane.position, {
      y: config.scenePosition?.[1] ?? -0.2,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
    timelines.push(tl);
  };

  // Click: emit event
  const onClick = () => {
    ctx.emit('navigate', { to: 'hub-pricing.select' });
  };

  // Assign handlers
  group.userData.handlers = {
    onHover,
    onHoverOut,
    onClick,
  };

  // ─────────────────────────────────────────────────────────────────
  // 7. CLEANUP
  // ─────────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach((tl) => tl.kill());
    gsap.killTweensOf(plane.position);

    // Cleanup cinematic primitives
    primitivesResults.forEach((r) => {
      if (r && r.cleanup) r.cleanup();
    });

    // Dispose materials and geometries
    material.dispose();
    planeGeom.dispose();
    backdropGeom.dispose();
    backdropMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();

    // Dispose textures
    if (baseTex) baseTex.dispose();
    if (depthTex) depthTex.dispose();
  };

  return group;
}
